const fs=require('fs'),path=require('path'),assert=require('assert/strict');
const {chromium}=require('C:/Users/Seba/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright');
(async()=>{const root=path.resolve(__dirname,'..'),b=await chromium.launch({headless:true,channel:'msedge'}),p=await b.newPage(),errors=[],base='http://127.0.0.1:4186/';p.on('pageerror',e=>errors.push(e.message));
const pages=['overview.html','product.html','stories/index.html',...Array.from({length:5},(_,i)=>`stories/us${i+1}.html`),'prototype.html','delivery.html','qa.html'];
for(const file of pages){const text=async full=>{await p.setContent(fs.readFileSync(full,'utf8'));return p.locator('main').evaluate(m=>{m.querySelectorAll('.decision-status,[data-refinement],[data-assumption],[aria-hidden=true]').forEach(e=>e.remove());m.querySelectorAll('tr').forEach(e=>{if(e.textContent.includes('US4 non-blocking question'))e.remove()});return m.textContent.replaceAll('Home Page context','Illustrative Reference').replaceAll('Q&As','Q&A')})};assert.equal(await text(path.join(root,file)),await text(path.join(root,'../deliverable-v4',file==='overview.html'?'index.html':file)),file+' content parity')}
for(const width of [1440,1250,768,390,320]){await p.setViewportSize({width,height:width<500?844:900});await p.goto(base);await p.evaluate(()=>document.fonts.ready);assert.ok(await p.evaluate(()=>document.fonts.check('800 80px Manrope')));assert.ok(await p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));assert.ok(await p.locator('.cover-cta').isVisible());assert.equal(await p.locator('.presentation-footer').count(),0);await p.screenshot({path:path.join(root,`evidence/v5-cover-${width}.png`),fullPage:true});await p.locator('.cover-cta').click();assert.match(p.url(),/overview.html$/);assert.equal(await p.locator('.presentation-footer').evaluate(e=>getComputedStyle(e).position),'static');await p.locator('.wordmark').click();assert.equal(new URL(p.url()).pathname,'/index.html')}
for(const file of ['index.html',...pages]){await p.goto(base+file);for(const href of await p.locator('a[href],link[href],script[src],img[src]').evaluateAll(es=>es.map(e=>e.getAttribute('href')||e.getAttribute('src')))){if(/^(https?:|data:|#)/.test(href))continue;const url=new URL(href,base+file);const r=await p.request.get(url.href);assert.ok(r.ok(),file+' -> '+href)}}
assert.deepEqual(errors,[]);await b.close();fs.writeFileSync(path.join(root,'evidence/v5-entrance.json'),JSON.stringify({result:'PASS',checks:['11 interior pages preserve exact main text from v4','Five viewport sizes 320–1440','Local Manrope loaded','No horizontal overflow','Cover → overview → cover','Overview CTA remains inline','Local page and asset links','No browser script errors']},null,2));console.log('PASS v5 entrance, content parity, five viewports, fonts and links');})();




